#include "realityforge/mesh_topology.hpp"
#include <fstream>
#include <sstream>
#include <iostream>
#include <iomanip>
using Key=std::array<std::array<double,3>,3>;
rf::SurfaceMesh read(const char* path){std::ifstream in(path);if(!in)throw std::runtime_error("missing input");std::string line;std::size_t nv=0,nf=0;while(std::getline(in,line)&&line!="end_header"){if(line.starts_with("element vertex "))nv=std::stoul(line.substr(15));if(line.starts_with("element face "))nf=std::stoul(line.substr(13));}if(nv>40000||nf>80000)throw std::runtime_error("bounds");rf::SurfaceMesh m;for(std::size_t i=0;i<nv;++i){std::getline(in,line);std::istringstream s(line);float x,y,z,nx,ny,nz;int r,g,b;if(!(s>>x>>y>>z>>nx>>ny>>nz>>r>>g>>b))throw std::runtime_error("bad vertex");rf::SurfaceVertex v;v.xyz={x,y,z};m.vertices.push_back(v);}for(std::size_t i=0;i<nf;++i){std::getline(in,line);std::istringstream s(line);unsigned n,a,b,c;if(!(s>>n>>a>>b>>c)||n!=3||a>=nv||b>=nv||c>=nv)throw std::runtime_error("bad face");m.triangles.push_back({a,b,c,0});}return m;}
Key key(const rf::SurfaceMesh&m,const rf::SurfaceTriangle&f){Key k;int n=0;for(auto id:{f.a,f.b,f.c}){auto p=m.vertices[id].xyz;k[n++]={p.x,p.y,p.z};}std::sort(k.begin(),k.end());return k;}
int main(int argc,char**argv){if(argc!=3)return 2;auto baseline=read(argv[1]),candidate=read(argv[2]);std::set<Key> old;for(auto f:baseline.triangles)old.insert(key(baseline,f));std::cout<<"{\n";int mn=0;for(auto* m:{&baseline,&candidate}){auto report=rf::analyzeMeshTopology(*m);std::map<std::string,std::size_t> counts;std::set<std::size_t> implicated;for(auto [i,j]:report.intersections){auto a=m->triangles[i],b=m->triangles[j];int oldCount=old.count(key(*m,a))+old.count(key(*m,b));int shared=0;for(auto x:{a.a,a.b,a.c})for(auto y:{b.a,b.b,b.c})if(x==y)++shared;using namespace rf::mesh_topology_detail;std::array<P,3> p{point(m->vertices[a.a].xyz),point(m->vertices[a.b].xyz),point(m->vertices[a.c].xyz)},q{point(m->vertices[b.a].xyz),point(m->vertices[b.b].xyz),point(m->vertices[b.c].xyz)};auto na=cross(sub(p[1],p[0]),sub(p[2],p[0])),nb=cross(sub(q[1],q[0]),sub(q[2],q[0]));auto la=len(na),lb=len(nb);bool coplanar=len(cross(na,nb))<=la*lb*1e-10L&&std::abs(dot(na,sub(q[0],p[0])))<=la*report.tolerance;std::string category=(oldCount==2?"old-old":oldCount==1?"old-added":"added-added");category+="/shared"+std::to_string(shared)+(coplanar?"/coplanar-overlap":"/noncoplanar-crossing");++counts[category];implicated.insert(i);implicated.insert(j);}if(mn)std::cout<<",\n";std::cout<<"\""<<(mn++?"candidate":"baseline")<<"\":{\"intersections\":"<<report.intersections.size()<<",\"ambiguousPairs\":"<<report.ambiguousPairs.size()<<",\"implicatedFaces\":"<<implicated.size()<<",\"intersectionCandidates\":"<<report.intersectionCandidates<<",\"budgetExceeded\":"<<(report.intersectionBudgetExceeded?"true":"false")<<",\"tolerance\":"<<std::setprecision(17)<<report.tolerance<<",\"classes\":{";bool first=true;for(auto&[k,v]:counts){if(!first)std::cout<<',';first=false;std::cout<<'"'<<k<<"\":"<<v;}std::cout<<"}}";}std::cout<<"\n}\n";}
